<?php
declare(strict_types=1);
return ['command'=>'redeem','description'=>'Redeem a fixed demo code','handler'=>static function(array $c):void{$id=$c['sender']['id']??null;if($id===null){bot_send($c['chat_id'],'Telegram profile details are unavailable.');return;}$code=trim($c['arguments']);if($code===''){bot_send($c['chat_id'],'Usage: /redeem DEMO-STARTER or /redeem DEMO-LAB');return;}$r=bot_user_redeem($id,$code);switch($r['status']){case 'not_registered':$text='Register first with /register.';break;case 'invalid_code':$text='❌ Unknown demo code. No credits were added.';break;case 'already_redeemed':$text='ℹ️ Code already redeemed. Current balance: <b>'.$r['balance'].'</b> credits.';break;default:$text="✅ <b>Demo code redeemed</b>\nAdded: <b>{$r['credits']}</b> credits\nBalance: <b>{$r['balance']}</b> credits\n\nCredits have no monetary value.";break;}bot_send($c['chat_id'],$text,bot_keyboard_dashboard());}];